// ===== CONFIGURACION =====
// Pasar a true SOLO cuando el reinicio de IIS este validado (ver README, seccion "Validar IIS").
const WINDOWS_HABILITADO = true;
// Zona horaria del servidor Zabbix (Costa Rica: UTC-6, sin horario de verano).
const TZ_ZABBIX = '-06:00';

const catalogo = {
  crm_linux:   { ambiente: 'A', so: 'linux',   host: '192.168.20.11', url: 'http://192.168.20.11:8080', tipos: ['http_down', 'container_down'], remediar: true },
  crm_windows: { ambiente: 'B', so: 'windows', host: '192.168.20.12', url: 'http://192.168.20.12',      tipos: ['http_down', 'service_down'],   remediar: WINDOWS_HABILITADO }
};

const b = $json.body || $json;
const t = catalogo[b.target];
const tipo = b.incident_type || null;
let autorizado = false;
let motivo = '';
if (!t) motivo = 'Objetivo no autorizado: ' + b.target;
else if (!tipo) motivo = 'El evento no trae incident_type';
else if (!t.tipos.includes(tipo)) motivo = 'Tipo de incidente no permitido para ' + b.target + ': ' + tipo;
else if (!t.remediar) motivo = 'Remediacion automatica de ' + b.target + ' deshabilitada: pendiente de validacion';
else autorizado = true;

// Hora del evento de Zabbix ("2026.10.15 14:05:30", en la zona de Zabbix) -> milisegundos
let t_evento_ms = null;
if (b.event_time) {
  const iso = String(b.event_time).trim().replace(/\./g, '-').replace(' ', 'T') + TZ_ZABBIX;
  const ms = Date.parse(iso);
  if (!isNaN(ms)) t_evento_ms = ms;
}
const ahora = Date.now();
return { json: {
  target: b.target || null,
  incident_type: tipo,
  event_id: b.event_id || null,
  event_time: b.event_time || null,
  autorizado,
  motivo,
  ambiente: t ? t.ambiente : null,
  so: t ? t.so : null,
  url: t ? t.url : null,
  host: t ? t.host : null,
  t_evento_ms,
  t_inicio_ms: ahora,
  t_inicio_n8n: new Date(ahora).toISOString()
} };

// Limite de reinicios por objetivo: maximo MAX en una ventana de VENTANA_MIN minutos.
// Nota: el workflow debe estar ACTIVO (ejecuciones de produccion) para que static data persista.
const MAX = 2;
const VENTANA_MIN = 15;
const ventanaMs = VENTANA_MIN * 60 * 1000;
const estado = $getWorkflowStaticData('global');
estado.reinicios = estado.reinicios || {};
const ahora = Date.now();
const d = $json;
const previos = (estado.reinicios[d.target] || []).filter(ts => ahora - ts < ventanaMs);
const permitido = previos.length < MAX;
if (permitido) previos.push(ahora);
estado.reinicios[d.target] = previos;
const minutosEspera = permitido ? 0 : Math.ceil((ventanaMs - (ahora - previos[0])) / 60000);
return { json: { ...d, permitido, intentos_en_ventana: previos.length, max_reinicios: MAX, ventana_min: VENTANA_MIN, minutos_espera: minutosEspera } };

// Se ejecuta despues del SSH de reinicio (Linux o Windows).
const c = $('Control de reinicios').first().json;
const ssh = $json;   // salida del SSH: { stdout, stderr, code } o { error } si no pudo conectarse
let error = '';
if (ssh.error) error = String(ssh.error.message || ssh.error);
else if (ssh.code !== 0 && ssh.code !== undefined) error = String(ssh.stderr || ssh.stdout || 'codigo ' + ssh.code);
return { json: {
  ...c,
  t_reinicio_ms: Date.now(),
  reinicio_ok: error === '',
  reinicio_error: error.slice(0, 300)
} };

// El HTTP respondio bien: se anota la hora antes de lanzar el RPA.
const r = $('Marcar hora del reinicio').first().json;
return { json: { ...r, t_http_ms: Date.now(), http_status: $json.statusCode } };

// Resultado tras reiniciar, HTTP correcto y RPA ejecutado en VM-08.
const r = $('Marcar hora de HTTP OK').first().json;
const ssh = $json;   // salida del SSH a VM-08; la ultima linea de stdout es un JSON
let rpa = { resultado: 'ERROR', segundos: null, pasos: [] };
try {
  const lineas = String(ssh.stdout || '').trim().split('\n');
  rpa = JSON.parse(lineas[lineas.length - 1]);
} catch (e) {
  rpa.mensaje = ssh.error
    ? 'Error SSH: ' + String(ssh.error.message || ssh.error)
    : 'Salida del RPA no interpretable: ' + String(ssh.stderr || ssh.stdout || '').slice(0, 200);
}
const ahora = Date.now();
const ref = r.t_evento_ms != null ? r.t_evento_ms : r.t_inicio_ms;
const seg = (a, b) => (a == null || b == null) ? null : Math.round((b - a) / 100) / 10;
const tiempos = {
  referencia: r.t_evento_ms != null ? 'evento Zabbix' : 'llegada del webhook',
  accion: seg(ref, r.t_reinicio_ms),
  recuperacion: seg(r.t_reinicio_ms, r.t_http_ms),
  rpa: rpa.segundos != null ? rpa.segundos : null,
  total: seg(ref, ahora)
};
const f = v => v == null ? 'n/d' : v + ' s';
const rpa_ok = rpa.resultado === 'PASS';
const pasos = (rpa.pasos || []).map(p => p.paso + ': ' + p.resultado + ' (' + p.segundos + ' s)').join(' | ');
const encabezado = rpa_ok ? '✅ RECUPERADO' : '⚠️ RECUPERADO, PERO EL RPA FALLO';
const mensaje = [
  encabezado + ': ' + r.target + ' (' + r.incident_type + ')',
  'Evento Zabbix: ' + (r.event_time || 'sin hora; se usa la llegada del webhook'),
  'Reinicio: ' + (r.reinicio_ok ? 'correcto' : 'con error: ' + r.reinicio_error) + ' | HTTP: ' + r.http_status,
  'T-accion: ' + f(tiempos.accion) + ' | T-recuperacion: ' + f(tiempos.recuperacion) + ' | T-total: ' + f(tiempos.total),
  'RPA ambiente ' + r.ambiente + ': ' + rpa.resultado + ' en ' + f(tiempos.rpa) + (pasos ? ' -> ' + pasos : ''),
  rpa.mensaje ? 'Detalle RPA: ' + rpa.mensaje : null,
  'Reinicios en ventana: ' + r.intentos_en_ventana + ' de ' + r.max_reinicios
].filter(Boolean).join('\n');
return { json: { ...r, estado: rpa_ok ? 'RECUPERADO' : 'RECUPERADO_RPA_FALLA', rpa, rpa_ok, tiempos, mensaje } };

// El HTTP no respondio bien tras el reinicio: no se ejecuta el RPA.
const r = $('Marcar hora del reinicio').first().json;
const http = $json;
const ahora = Date.now();
const ref = r.t_evento_ms != null ? r.t_evento_ms : r.t_inicio_ms;
const seg = (a, b) => (a == null || b == null) ? null : Math.round((b - a) / 100) / 10;
const tiempos = {
  referencia: r.t_evento_ms != null ? 'evento Zabbix' : 'llegada del webhook',
  accion: seg(ref, r.t_reinicio_ms),
  recuperacion: null,
  rpa: null,
  total: seg(ref, ahora)
};
const f = v => v == null ? 'n/d' : v + ' s';
const estadoHttp = http.statusCode !== undefined ? http.statusCode : 'sin respuesta';
const mensaje = [
  '❌ FALLO: ' + r.target + ' (' + r.incident_type + ') sigue sin responder tras el reinicio.',
  'Evento Zabbix: ' + (r.event_time || 'sin hora; se usa la llegada del webhook'),
  'Reinicio: ' + (r.reinicio_ok ? 'ejecutado' : 'con error: ' + r.reinicio_error) + ' | HTTP: ' + estadoHttp,
  'T-accion: ' + f(tiempos.accion) + ' | T-total hasta el fallo: ' + f(tiempos.total),
  'Se requiere intervencion humana. El RPA no se ejecuto.',
  'Reinicios en ventana: ' + r.intentos_en_ventana + ' de ' + r.max_reinicios
].join('\n');
return { json: { ...r, estado: 'FALLO', tiempos, mensaje } };

